// Na Androidu zamjenjuje pywebview: pozive api.metoda(...) šalje Kotlin kodu (AndroidBridge) i vraća Promise.
// Na desktopu (nema AndroidBridge) ne radi ništa.
(function () {
  if (!window.AndroidBridge || window.pywebview) return;
  const pending = {};
  let seq = 0;
  window.__cb = function (id, ok, data) {
    const p = pending[id]; delete pending[id];
    if (!p) return;
    if (ok) p.res(data); else p.rej(new Error(String(data)));
  };
  const api = new Proxy({}, {
    get: (_, name) => {
      if (typeof name !== "string" || name === "then") return undefined;
      return (...args) => new Promise((res, rej) => {
        const id = ++seq; pending[id] = { res, rej };
        window.AndroidBridge.call(id, name, JSON.stringify(args));
      });
    },
  });
  window.pywebview = { api };

  const root = document.documentElement;
  root.classList.add("android");
  let tv = false; try { tv = window.AndroidBridge.isTv(); } catch (e) {}
  if (tv) root.classList.add("tv");

  const css = document.createElement("style");
  css.textContent = `
    html.android button, html.android select { min-height:40px; }
    html.android :focus-visible, html.android button:focus, html.android select:focus { outline:3px solid #ffd54a; outline-offset:1px; }
    html.tv body { zoom:1.35; }
    html.tv button, html.tv select { min-height:46px; }
    @media (max-width: 899px) {
      html.android #app { display:flex; flex-direction:column; }
      html.android #main { order:1; flex:none; }
      html.android #stage { flex:none; height:32vh; }
      html.android #bar { max-height:24vh; overflow-y:auto; }
      html.android #side { order:2; flex:1; border-right:0; min-height:0; }
    }`;
  document.head.appendChild(css);

  // dodir na stavku liste = odmah pusti (dvoklik nema smisla na ekranu osjetljivom na dodir)
  document.addEventListener("DOMContentLoaded", () => {
    const list = document.getElementById("list");
    if (list) list.addEventListener("click", (e) => {
      const row = e.target.closest && e.target.closest(".row");
      if (row) row.dispatchEvent(new MouseEvent("dblclick", { bubbles: true }));
    });
    window.dispatchEvent(new Event("pywebviewready"));
  });
})();
